/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Candidate
 *   Functions: release, candidate, view, keys, bestOf, discNumbers, numberOnes, live, reshaped
 *   Constants: bestOfContext, liveContext
 * Tests
 *   - titles compare after width, case, a trailing credit, a leading or trailing primary Artist name or part, and brackets are folded
 *   - editions sharing every value but media and country are one release; the sections list possible matches, the other releases that fit, then the rest
 *   - the track titles give Disc and Track Numbers only for positions of one form increasing in Album order, and only empty numbers fill
 *   - a track title's position reads as written, of the forms the numbers are filled from, and a title without one has none
 *   - a track title's rest is exactly its text after the position, whitespace collapsed as the server keeps it, and a title without a position has none
 *   - the track titles read the positions the server lookup removes, row by row of its table
 *   - each card gives one reason, the first that applies
 *   - the fit of a no-match run: an empty Album's same-title releases; else possible matches before other fits, with the cause in its order
 *   - a release applied for its Album values only is offered again only once its pairing is single and only for the applied status
 *   - the possible releases a review names are its matching groups, else the release groups its tracks fit (possible matches first), never its records
 * @end-catalog */

import type { ReviewLookupView } from './importLookupApi';
import { pairedLookupResponse, pairingApplication, pairingEditions, pairingLookupResponse } from './catalogReviewLookupFixtures.testSupport';
import { candidateReason, editionKey, normalizedTitle, releaseGroups, reviewAppliedAgain, reviewLookupFit, reviewReleaseCount, reviewSections, titleLeadingPosition, titleNumbers,
  titlePosition, titleTier } from './reviewLookupStatus';

/**
 * The review's own reading of its lookup view, without rendering: normalized titles, releases and their editions, the sections,
 * how many possible releases it names, the Disc and Track Numbers titles give, and each card's reason (the status line has its own
 * tests, reviewStatusLine.test.ts). The views keep the shapes of real runs (a live Album without numbers, an Album without durations, an Album without
 * members); every name and identifier is synthetic, except the titles of the server's position table, which the parity test
 * repeats as they are.
 */
type Candidate = ReviewLookupView['candidates'][number];
const release = (n: number) => `0000000b-0000-4000-8000-${String(n).padStart(12, '0')}`;
/** A review candidate: unverified with two members fitting in more than one way unless `extra` says otherwise. */
const candidate = (n: number, title: string, extra: Partial<Candidate> & { pairing?: 'unique' | 'ambiguous' | 'none' | null; local?: number; unknown?: number; differences?: string[] } = {}): Candidate => {
  const { pairing = 'ambiguous', local = 2, unknown = 0, differences = [], ...rest } = extra;
  return { key: `musicbrainz:${release(n)}`, releaseId: release(n), source: 'musicbrainz', notChecked: false, status: 'unverified', title, artist: 'Synthetic Singer', label: 'Synthetic Label',
    catalogNumber: `SYN-${n}`, barcode: String(4006381330000 + n), country: 'JP', date: { year: 2016, month: 1, day: 1 }, formats: ['CD'], trackCount: 44,
    comparison: { trackCount: { local, candidate: 44 }, discCount: { local: null, candidate: 3 }, differences: differences as never, unknownLocalDurations: unknown, unknownCandidateDurations: 0,
      subset: { leftOutTracks: 0, pairing, pairs: [], missingTrackCount: 44 - local, unpairableSlotIds: [] } }, groupKey: null, artistMismatch: false, artwork: false, byTrackTitle: false, ...rest };
};
const view = (candidates: Candidate[], extra: Partial<ReviewLookupView> = {}): ReviewLookupView => ({ ...pairingLookupResponse().lookup!, input: { trigger: 'catalog', submitted: null },
  candidates, disclosure: { unknownLocalDurations: 0, unknownLocalDiscNumbers: 0, partialComparison: false }, ...extra });
const keys = (groups: Candidate[][]) => groups.map(group => group.map(entry => entry.title));
/** An Album without durations: 14 releases its tracks fit (a song release first, the four editions of its best-of last), and two that do not fit. */
const bestOf = () => view([candidate(1, 'Synthetic Seven Sins', { unknown: 3, local: 3 }), candidate(2, 'Synthetic Snow Flower', { unknown: 3, local: 3, artistMismatch: true }),
  candidate(3, 'Synthetic Snow Flower', { unknown: 3, local: 3, barcode: '4006381339999' }), candidate(4, 'SYNTHETIC SEVENTEEN', { unknown: 3, local: 3, source: 'itunes', key: 'itunes:16893585', releaseId: '16893585' }),
  candidate(5, 'Synthetic Message', { unknown: 3, local: 3 }), candidate(6, 'Synthetic Best', { unknown: 3, local: 3, artistMismatch: true }), candidate(7, 'Synthetic Best', { unknown: 3, local: 3, barcode: '1' }),
  candidate(8, 'Synthetic Will', { unknown: 3, local: 3 }), candidate(9, 'Synthetic Love', { unknown: 3, local: 3 }), candidate(10, 'Synthetic Stars', { unknown: 3, local: 3 }),
  ...[11, 12, 13, 14].map(n => candidate(n, 'Synthetic Best BIBLE', { unknown: 3, local: 3 })),
  candidate(15, 'Synthetic Single', { status: 'notMatching', pairing: 'none', local: 3, differences: ['trackCount'] }), candidate(16, 'Synthetic Live', { status: 'incomplete', comparison: null })],
{ disclosure: { unknownLocalDurations: 3, unknownLocalDiscNumbers: 3, partialComparison: true } });
/** What the titles give: a Disc and Track Number per member, or nothing left to fill. */
const discNumbers = (count: number) => ({ numbers: {}, count, disc: true });
const bestOfContext = { members: 3, searched: 'Synthetic Best BIBLE／Synthetic Singer', artists: ['Synthetic Singer'], now: 0, numbers: discNumbers(3) };
/** An Album without members: 25 releases found by its title alone, six of them with exactly its title. */
const numberOnes = () => view(Array.from({ length: 25 }, (_, index) => candidate(index + 1, index % 4 === 0 && index < 24 ? 'Synthetic Number Ones' : index % 2 ? `Synthetic Number Ones ${index}` : `Other ${index}`,
  { local: 0, pairing: 'unique' })));
const live = (extra: Partial<ReviewLookupView> = {}) => ({ ...pairingLookupResponse().lookup!, ...extra });
const liveContext = { members: 2, searched: 'Synthetic Live Album 2', artists: ['Synthetic Live Artist -Romanized-'], now: 0, numbers: discNumbers(2) };
/** The live Album's run with every unverified candidate's pairing and unknown durations replaced. */
const reshaped = (pairing: 'unique' | 'ambiguous', unknown = 0) => view(live().candidates.map(entry => entry.status === 'unverified'
  ? { ...entry, comparison: { ...entry.comparison!, unknownLocalDurations: unknown, subset: { ...entry.comparison!.subset!, pairing } } } : entry),
{ disclosure: { unknownLocalDurations: unknown, unknownLocalDiscNumbers: 2, partialComparison: true } });

test('titles compare after width, case, a trailing credit, a leading or trailing primary Artist name or part, and brackets are folded', () => {
  expect(normalizedTitle('Synthetic Best BIBLE／Synthetic Singer', ['Synthetic Singer'])).toBe('synthetic best bible');
  expect(normalizedTitle('Synthetic Ultimate Best／Synthetic Label', [])).toBe('synthetic ultimate best');
  for (const name of ['Synthetic Artist -Romanized-', 'Synthetic Artist (Romanized)']) expect(normalizedTitle('Synthetic Artist 2nd Album「色彩」', [name])).toBe('2nd album 色彩');
  expect(normalizedTitle('Synthetic Live 2 Romanized', ['Synthetic Artist -Romanized-'])).toBe('synthetic live 2');
  expect(normalizedTitle('Ｓｙｎｔｈｅｔｉｃ　Ｌｉｖｅ　２（Ｌｉｖｅ）', [])).toBe('synthetic live 2 live');
  // A title that is only the Artist's name, or only a credit, keeps it.
  expect(normalizedTitle('Synthetic Singer', ['Synthetic Singer'])).toBe('synthetic singer');
  expect(normalizedTitle('／Synthetic', [])).toBe('/synthetic');
  // Only a credit after a full-width slash, or after an ASCII one with spaces on both sides, is removed; a slash inside a title stays.
  expect([normalizedTitle('Love/Hate', []), normalizedTitle('Love/Peace', []), normalizedTitle('AC/DC Live', []), normalizedTitle('Synthetic Best / Synthetic Label', [])])
    .toEqual(['love/hate', 'love/peace', 'ac/dc live', 'synthetic best']);
  expect(titleTier(normalizedTitle('Fate/Zero Synthetic Soundtrack', []), normalizedTitle('Fate/stay night Synthetic Soundtrack', []))).toBe('other');
  // A credit beside a bracket is removed once the brackets are spaces.
  expect(normalizedTitle('「色彩」Synthetic Artist', ['Synthetic Artist -Romanized-'])).toBe('色彩');
  expect([titleTier('a b', 'a b'), titleTier('a b c', 'a b'), titleTier('a', 'a b'), titleTier('a', 'b'), titleTier('', 'a'), titleTier('a', '')]).toEqual(['same', 'similar', 'similar', 'other', 'other', 'other']);
});

test('editions sharing every value but media and country are one release; the sections list possible matches, the other releases that fit, then the rest', () => {
  const [digital, cd] = live().candidates.slice(-2);
  expect(editionKey(digital)).toBe(editionKey(cd));
  for (const change of [{ barcode: '1' }, { catalogNumber: 'SYN-1' }, { trackCount: 21 }, { date: { year: 2023, month: 3, day: null } }])
    expect(editionKey({ ...digital, ...change } as Candidate)).not.toBe(editionKey(digital));
  expect(releaseGroups([digital, live().candidates[0], cd]).map(group => group.map(entry => entry.key))).toEqual([[...pairingEditions], [live().candidates[0].key]]);
  // A live Album: one possible release with two editions in the server's order, nothing else that fits, ten that do not.
  let sections = reviewSections(live().candidates, liveContext.searched, liveContext.artists);
  expect([sections.possible.map(group => group.map(entry => entry.key)), sections.others.length, sections.rest.length]).toEqual([[[...pairingEditions]], 0, 10]);
  // An Album without durations: its best-of's four editions differ in barcode, so they are four releases; the others fit by a similar
  // title first, then by a credit that agrees, then in the server's order; the release that does not fit and the unread one come last.
  sections = reviewSections(bestOf().candidates, bestOfContext.searched, bestOfContext.artists);
  expect(keys(sections.possible)).toEqual([['Synthetic Best BIBLE'], ['Synthetic Best BIBLE'], ['Synthetic Best BIBLE'], ['Synthetic Best BIBLE']]);
  expect(keys(sections.others)).toEqual([['Synthetic Best'], ['Synthetic Best'], ['Synthetic Seven Sins'], ['Synthetic Snow Flower'], ['SYNTHETIC SEVENTEEN'], ['Synthetic Message'],
    ['Synthetic Will'], ['Synthetic Love'], ['Synthetic Stars'], ['Synthetic Snow Flower']]);
  expect(sections.others.slice(0, 2).map(([entry]) => entry.artistMismatch)).toEqual([false, true]);
  expect(keys(sections.rest)).toEqual([['Synthetic Single'], ['Synthetic Live']]);
  // Without an equal title, a similar one is a possible match.
  sections = reviewSections(bestOf().candidates.filter(entry => entry.title !== 'Synthetic Best BIBLE'), bestOfContext.searched, bestOfContext.artists);
  expect(keys(sections.possible)).toEqual([['Synthetic Best'], ['Synthetic Best']]);
});

test('the track titles give Disc and Track Numbers only for positions of one form increasing in Album order, and only empty numbers fill', () => {
  const tracks = (titles: string[], numbers: [number | null, number | null][] = []) => titles.map((title, index) => ({ slotId: `slot-${index + 1}`, title,
    discNumber: numbers[index]?.[0] ?? null, trackNumber: numbers[index]?.[1] ?? null }));
  const all = (count: number) => new Set(Array.from({ length: count }, (_, index) => `slot-${index + 1}`));
  expect(titleNumbers(tracks(['1-01 Synthetic opening (Live)', '1-02 Synthetic second (Live)']), all(2))).toEqual({ count: 2, disc: true,
    numbers: { 'slot-1': { discNumber: 1, trackNumber: 1 }, 'slot-2': { discNumber: 1, trackNumber: 2 } } });
  expect(titleNumbers(tracks(['1.01.合成の華', '1.02.WILL', '1.03.合成恋 ～SAI_REN～']), all(3))!.numbers).toEqual({ 'slot-1': { discNumber: 1, trackNumber: 1 },
    'slot-2': { discNumber: 1, trackNumber: 2 }, 'slot-3': { discNumber: 1, trackNumber: 3 } });
  expect(titleNumbers(tracks(['1.01. 合成(Instrumental)', '2.01. 合成のワルツ']), all(2))!.numbers).toEqual({ 'slot-1': { discNumber: 1, trackNumber: 1 }, 'slot-2': { discNumber: 2, trackNumber: 1 } });
  // A Track Number alone gives no Disc Number, even where one was captured.
  for (const titles of [['01.Synthetic', '02.Synthetic'], ['01 Synthetic', '02 Synthetic'], ['01 - Synthetic', '02 - Synthetic'], ['1 \u2013 Synthetic', '3 . Synthetic'], ['1. Synthetic', '2. Synthetic']]) {
    const found = titleNumbers(tracks(titles), all(2));
    expect([found?.disc, found?.numbers], titles.join()).toEqual([false, { 'slot-1': { trackNumber: Number(/\d+/.exec(titles[0])![0]) }, 'slot-2': { trackNumber: Number(/\d+/.exec(titles[1])![0]) } }]);
  }
  expect(titleNumbers(tracks(['1-01 Synthetic']), all(1))).toEqual({ count: 1, disc: true, numbers: { 'slot-1': { discNumber: 1, trackNumber: 1 } } });
  // Titles that only look numbered never count: a lone Track Number or unpadded Disc and Track Number, another separator, mixed
  // forms, repeated or decreasing positions, a zero, or nothing after the separator.
  for (const titles of [['7 Synthetic Rings'], ['01 Synthetic'], ['1-1 Synthetic'], ['1-2 Synthetic Punch'], ['1-800 Synthetic Hotline'], ['7 Synthetic Rings', 'Synthetic Thanks'],
    ['7 Synthetic Rings', '99 Synthetic Balloons', '24 Synthetic Hours'], ['1_Synthetic', '3) Synthetic'], ['01-Synthetic', '02-Synthetic'], ['1999 Synthetic', '2000 Synthetic'],
    ['Synthetic', 'Other'], ['1-01 Synthetic', '02 Synthetic'], ['01 Synthetic', '01 Again'], ['02 Synthetic', '01 Synthetic'], ['1-01 Synthetic', '1-01 Again'],
    ['1-02 Synthetic', '1-01 Synthetic'], ['2-01 Synthetic', '1-02 Synthetic'], ['2.0 Synthetic Remix', '3.0 Synthetic'], ['0 Synthetic', '1 Synthetic'], ['01.', '02.'], []]) {
    expect(titleNumbers(tracks(titles), all(titles.length)), titles.join()).toBeNull();
  }
  // The known limit, as on the server: titles that all start with increasing numbers read as positions.
  expect(titleNumbers(tracks(['7 Synthetic Rings', '99 Synthetic Balloons']), all(2))!.numbers).toEqual({ 'slot-1': { trackNumber: 7 }, 'slot-2': { trackNumber: 99 } });
  // A saved number is kept, a Disc Number is set only where it was captured, and nothing left to fill counts nothing.
  expect(titleNumbers(tracks(['1-01 A', '1-02 B'], [[null, 1], [null, null]]), new Set(['slot-2']))).toEqual({ count: 1, disc: true, numbers: { 'slot-2': { discNumber: 1, trackNumber: 2 } } });
  expect(titleNumbers(tracks(['1-01 A', '1-02 B'], [[1, 1], [1, 2]]), all(2))).toEqual({ count: 0, disc: true, numbers: {} });
  expect(titleNumbers(tracks(['1-01 A', '1-02 B'], [[1, 1], [null, null]]), all(2))!.numbers).toEqual({ 'slot-2': { discNumber: 1, trackNumber: 2 } });
  // A saved number that disagrees with its own title fills nothing, so no two members claim one position.
  expect(titleNumbers(tracks(['01 A', '02 B'], [[null, 2], [null, null]]), all(2))).toBeNull();
  expect(titleNumbers(tracks(['01 A', '02 B'], [[null, 5], [null, null]]), all(2))).toBeNull();
  expect(titleNumbers(tracks(['1-01 A', '1-02 B'], [[2, null], [null, null]]), all(2))).toBeNull();
  // Titles on several discs fill nothing where a member's Disc Number was never captured.
  expect(titleNumbers(tracks(['1-01 A', '2-01 C']), new Set())).toBeNull();
  expect(titleNumbers(tracks(['1-01 A', '1-02 B']), new Set())).toEqual({ count: 2, disc: true, numbers: { 'slot-1': { trackNumber: 1 }, 'slot-2': { trackNumber: 2 } } });
});

test('a track title\'s position reads as written, of the forms the numbers are filled from, and a title without one has none', () => {
  expect(['1-01 Synthetic opening (Live)', '1.01.合成の華', '01 - Synthetic', '  2-08   Synthetic', '7 Synthetic Rings'].map(titlePosition)).toEqual(['1-01', '1.01', '01', '2-08', '7']);
  expect(['Synthetic opening', '01_Synthetic', '12) Synthetic', '01-Synthetic', ''].map(titlePosition)).toEqual([null, null, null, null, null]);
});

test('a track title\'s rest is exactly its text after the position, whitespace collapsed as the server keeps it, and a title without a position has none', () => {
  const rest = (title: string) => titleLeadingPosition(title)?.rest ?? null;
  expect(['1-01 Yorugaonokokuhaku(Live)', '1.01.雪の華', '1.01. 創生(Instrumental)', '01 - 序曲', '2-12 Synthetic  Song ', ' 01  X', '01 . X', '1-01 \u2014 X', '01 ...Baby One More Time',
    '01 -X', '7 Rings'].map(rest)).toEqual(['Yorugaonokokuhaku(Live)', '雪の華', '創生(Instrumental)', '序曲', 'Synthetic Song', 'X', 'X', 'X', '...Baby One More Time', '-X', 'Rings']);
  // No position: a year, a prefix the server does not read, a zero, no text after the separator, or a title over 1024 characters.
  expect(['1999 X', 'Disc2-03 X', '01_X', '12) X', '01-X', '0 X', '1-0 X', '0-1 X', '01', '01.', 'X', '', `01 ${'x'.repeat(1022)}`].map(rest)).toEqual(Array(13).fill(null));
  expect([titleLeadingPosition('2-12 Synthetic'), titleLeadingPosition('012 Synthetic'), titleLeadingPosition('0 X')]).toEqual([{ discNumber: 2, trackNumber: 12, rest: 'Synthetic' },
    { discNumber: null, trackNumber: 12, rest: 'Synthetic' }, null]);
});

test('the track titles read the positions the server lookup removes, row by row of its table', () => {
  // The rows of test/administration/lookupTitlePositions.test.ts with the same titles; its non-string values have no counterpart,
  // as saved titles are strings. Every number is empty and every Disc Number captured, so the fill shows what the guard accepts.
  const fill = (titles: readonly string[]) => titleNumbers(titles.map((title, index) => ({ slotId: `slot-${index + 1}`, title, discNumber: null, trackNumber: null })),
    new Set(titles.map((_, index) => `slot-${index + 1}`)))?.numbers ?? null;
  const at = (discNumber: number | null, trackNumber: number) => ({ ...(discNumber === null ? {} : { discNumber }), trackNumber });
  // Each title's own reading, shown before a later position of the same form, since a lone Track Number never counts.
  for (const [title, discNumber, trackNumber] of [
    ['1-01 Yorugaonokokuhaku(Live)', 1, 1], ['1.01.雪の華', 1, 1], ['1.01. 創生(Instrumental)', 1, 1], ['01 X', null, 1], ['01 - X', null, 1], ['01.X', null, 1],
    ['001 X', null, 1], [' 01  X', null, 1], ['1-01 - X', 1, 1], ['1-01. X', 1, 1], ['2-12 Synthetic  Song ', 2, 12], ['7 Rings', null, 7],
    // A spaced period, hyphen or dash goes with the position; a space before other punctuation leaves it in the rest.
    ['01 . X', null, 1], ['01 \u2013 X', null, 1], ['1-01 \u2014 X', 1, 1], ['01 ...Baby One More Time', null, 1], ['01 -X', null, 1]
  ] as const) {
    expect(fill([title, discNumber === null ? '999 Later' : '99-999 Later']), title).toEqual({ 'slot-1': at(discNumber, trackNumber), 'slot-2': at(discNumber === null ? null : 99, 999) });
  }
  expect(fill(['99-998 W', '99-999 X'])).toEqual({ 'slot-1': at(99, 998), 'slot-2': at(99, 999) });
  // No position: numbers out of range or zero, no separator or text after it, another separator, full-width digits, a year.
  for (const title of ['100-01 X', '1000 X', '0 X', '1-0 X', '0-1 X', '01', '01.', '01X', '01-X', '01_X', '12) X', '１．０１．X', 'X', '1999 X', 'Room404', '7',
    `01 ${'x'.repeat(1022)}`]) {
    for (const later of ['999 Later', '99-999 Later']) expect(fill([title, later]), title).toBeNull();
  }
  expect(fill(['1-01 A', '1-02 B'])).toEqual({ 'slot-1': at(1, 1), 'slot-2': at(1, 2) });
  expect(fill(['1-01 A', '2-01 B'])).toEqual({ 'slot-1': at(1, 1), 'slot-2': at(2, 1) });
  expect(fill(['1-01 A', '1.02.B', '1-03 - C'])).toEqual({ 'slot-1': at(1, 1), 'slot-2': at(1, 2), 'slot-3': at(1, 3) });
  expect(fill(['01 A', '02.B', '03 - C'])).toEqual({ 'slot-1': at(null, 1), 'slot-2': at(null, 2), 'slot-3': at(null, 3) });
  expect(fill(['1.01.雪の華', '1.02.WILL', '1.03.彩恋 ～SAI_REN～'])).toEqual({ 'slot-1': at(1, 1), 'slot-2': at(1, 2), 'slot-3': at(1, 3) });
  // Positions of both forms on one Album never count, whatever their order.
  for (const titles of [['01 A', '1-02 B'], ['1-02 A', '03 B'], ['1-01 A', '02 B', '1-03 C'], ['2-01 A', '05 B'], ['01 A', '01 B'], ['02 A', '01 B'], ['1-02 A', '1-02 B'],
    ['7 Rings', 'thank u, next'], ['7 Rings', '99 Luftballons', '24 Hours'], ['Room404', 'Room405'], [], ['01 A', 'B']]) {
    expect(fill(titles), JSON.stringify(titles)).toBeNull();
  }
  // A lone title counts only with a Disc Number and a zero-padded Track Number, so a single keeps a leading number or decimal.
  expect(fill(['1-01 A'])).toEqual({ 'slot-1': at(1, 1) });
  expect(fill(['1.01.雪の華'])).toEqual({ 'slot-1': at(1, 1) });
  expect(fill(['2-005 A'])).toEqual({ 'slot-1': at(2, 5) });
  for (const titles of [['7 Rings'], ['01 A'], ['01. A'], ['Room404'], ['1.5 Seconds'], ['1-2 Punch'], ['1.21 Gigawatts'], ['3.14 Pi'], ['2.5 Something'], ['1-5 A'], ['1-12 A']]) {
    expect(fill(titles), JSON.stringify(titles)).toBeNull();
  }
  // The known limit: titles that all start with increasing numbers read as positions, since nothing tells them apart.
  expect(fill(['24 Hours', '99 Luftballons'])).toEqual({ 'slot-1': at(null, 24), 'slot-2': at(null, 99) });
});

test('each card gives one reason, the first that applies', () => {
  const members = (slotIds: readonly string[]) => slotIds.join(', ');
  const reason = (entry: Candidate) => candidateReason(entry, members);
  const base = candidate(1, 'Synthetic');
  expect(reason({ ...base, status: 'incomplete', comparison: null })).toEqual({ key: 'lookup.status_incomplete' });
  expect(reason(candidate(1, 'X', { local: 0, pairing: 'unique' }))).toEqual({ key: 'catalog_review.lookup_reason_empty_album', values: undefined });
  // An Album without members names why a release does not fit, not that the Album is empty.
  expect(reason(candidate(1, 'X', { local: 0, pairing: null, status: 'notMatching', differences: ['tooManyTracks'] }))).toEqual({ key: 'lookup.difference_tooManyTracks' });
  expect(reason(candidate(1, 'X', { status: 'notMatching', pairing: 'none', differences: ['trackCount', 'pairing'] }))).toEqual({ key: 'catalog_review.lookup_reason_too_few_tracks',
    values: { candidate: 44, local: 2 } });
  expect(reason(candidate(1, 'X', { status: 'notMatching', differences: ['tooManyTracks', 'tracklistInvalid'] }))).toEqual({ key: 'lookup.difference_tooManyTracks' });
  expect(reason(candidate(1, 'X', { status: 'notMatching', differences: ['tracklistInvalid'] }))).toEqual({ key: 'lookup.difference_tracklistInvalid' });
  const unpairable = candidate(1, 'X', { status: 'notMatching', pairing: 'none', differences: ['pairing'] });
  unpairable.comparison!.subset!.unpairableSlotIds = ['slot-2', 'slot-3'];
  expect(reason(unpairable)).toEqual({ key: 'catalog_review.lookup_unpairable', values: { tracks: 'slot-2, slot-3' } });
  expect(reason(candidate(1, 'X', { status: 'notMatching', pairing: 'none', differences: ['pairing'] }))).toEqual({ key: 'catalog_review.lookup_reason_no_distinct', values: undefined });
  expect(reason(candidate(1, 'X', { status: 'notMatching', pairing: 'unique', differences: ['duration'] }))).toEqual({ key: 'lookup.status_notMatching' });
  expect(reason(candidate(1, 'X', { unknown: 2 }))).toEqual({ key: 'catalog_review.lookup_reason_no_durations', values: { count: 2 } });
  expect(reason(candidate(1, 'X'))).toEqual({ key: 'catalog_review.lookup_reason_ambiguous', values: { count: 2 } });
  expect(reason(candidate(1, 'X', { pairing: 'unique', unknown: 1 }))).toEqual({ key: 'catalog_review.lookup_reason_paired_no_durations', values: { count: 1 } });
  expect(reason(candidate(1, 'X', { pairing: 'unique' }))).toEqual({ key: 'catalog_review.lookup_reason_release_durations', values: undefined });
  expect(reason(candidate(1, 'X', { pairing: null }))).toEqual({ key: 'lookup.status_unverified' });
  expect(reason(candidate(1, 'X', { status: 'matching', pairing: 'unique' }))).toEqual({ key: 'catalog_review.lookup_reason_matching', values: { count: 2 } });
});

test('the fit of a no-match run: an empty Album\'s same-title releases; else possible matches before other fits, with the cause in its order', () => {
  const empty = reviewLookupFit(numberOnes(), { members: 0, searched: 'Synthetic Number Ones', artists: [] });
  expect(empty && !empty.members && keys(empty.releases)).toEqual(Array.from({ length: 6 }, () => ['Synthetic Number Ones']));
  // Members without a duration come before a pairing that is not single; the best-of's four editions differ in barcode.
  expect(reviewLookupFit(bestOf(), bestOfContext)).toMatchObject({ members: true, possible: true, cause: 'durations', unknown: 3 });
  expect((reviewLookupFit(bestOf(), bestOfContext) as { releases: Candidate[][] }).releases).toHaveLength(4);
  expect(reviewLookupFit(view(live().candidates), liveContext)).toMatchObject({ members: true, possible: true, cause: 'pairing', unknown: 0 });
  expect(reviewLookupFit(reshaped('unique'), liveContext)).toMatchObject({ cause: 'release_durations' });
  // One release that pairs in one way is enough, whatever the others.
  const mixed = view(live().candidates.map((entry, index) => entry.status === 'unverified' && index === live().candidates.findIndex(other => other.status === 'unverified')
    ? { ...entry, comparison: { ...entry.comparison!, subset: { ...entry.comparison!.subset!, pairing: 'unique' as const } } } : entry), { disclosure: live().disclosure });
  expect(reviewLookupFit(mixed, liveContext)).toMatchObject({ cause: 'release_durations' });
  expect(reviewLookupFit(reshaped('unique', 1), liveContext)).toMatchObject({ cause: 'paired_durations', unknown: 1 });
  // With no possible match, the releases whose titles differ are the fit; nothing that fits is a real no match.
  const other = reviewLookupFit(view(live().candidates), { ...liveContext, searched: 'Unrelated Synthetic Title' });
  expect(other).toMatchObject({ members: true, possible: false, cause: 'pairing' });
  expect(reviewLookupFit(view(live().candidates.filter(entry => entry.status !== 'unverified')), liveContext)).toBeNull();
});

test('a release applied for its Album values only is offered again only once its pairing is single and only for the applied status', () => {
  const again = pairedLookupResponse(pairingApplication(pairingEditions[0], false)).lookup!;
  expect(reviewAppliedAgain(again, 'lookup.applied')?.key).toBe(pairingEditions[0]);
  expect(reviewAppliedAgain(again, 'lookup.applied_itunes')).toBeUndefined();
  expect(reviewAppliedAgain(pairedLookupResponse(pairingApplication(pairingEditions[0], true)).lookup!, 'lookup.applied')).toBeUndefined();
  expect(reviewAppliedAgain({ ...pairingLookupResponse().lookup!, applied: pairingApplication(pairingEditions[0], false) }, 'lookup.applied')).toBeUndefined();
});

test('the possible releases a review names are its matching groups, else the release groups its tracks fit (possible matches first), never its records', () => {
  // 14 records the tracks fit: 4 possible releases with exactly the searched title and 10 others; the count is 4, not 14.
  expect(bestOf().candidates.filter(entry => entry.status === 'unverified')).toHaveLength(14);
  expect(reviewReleaseCount(bestOf(), bestOfContext.searched, bestOfContext.artists)).toBe(4);
  // Without a possible match the other fits count, as releases (editions of one release count once).
  expect(reviewReleaseCount(bestOf(), 'Synthetic Unrelated', bestOfContext.artists)).toBe(14);
  expect(reviewReleaseCount(live(), 'Synthetic Budokan', liveContext.artists)).toBe(1);
  // Matching groups count as they are; nothing that fits counts none.
  expect(reviewReleaseCount(view(bestOf().candidates, { groups: [{}, {}] as never }), bestOfContext.searched, bestOfContext.artists)).toBe(2);
  expect(reviewReleaseCount(view([]), bestOfContext.searched, bestOfContext.artists)).toBe(0);
});
